%[text] # Demo 3: Feedforward Control Experiment
%[text] Run this live script from the project root. 
%[text] Trajectory generation requires Symbolic Math Toolbox. 
%[text] external target and must be run by the experiment operator.
%[text] ## 1. Load settings and design the feedback controller
clear; close all;
projectRoot = fileparts(fileparts(mfilename("fullpath")));
run(fullfile(projectRoot, "config", "config_tunable.m"));
load(fullfile(projectRoot, "config", "data", "pana_params.mat"));
[plant, plantPath] = load_experiment_plant( ...
    projectRoot, plantDataFile, Ts);
Pd = plant.Pd;
Jn = plant.Jn;
Dn = plant.Dn;
Ndelay = plant.Ndelay;
fprintf("Sample rate: %.0f Hz, plant: %s\n", 1/Ts, plantPath); %[output:8bc5af1b]

Pd0 = struct( ...
    "m", Jn, ...
    "d", Dn, ...
    "k", 0, ...
    "delay", Ndelay, ...
    "lp", [0, 0, 0]);
[~, Gn0] = modelCreate(Pd0, Ts, Pd.Frequency);
Pdn = Gn0.modelDelayed;

[fb, ~, ~] = fbDesign(Pd, Ts);
Cd = fb.K;
Kd = fb.K;
%%
%[text] ## Check stability and sensitivity before operating the stage
figure; %[output:7ea341fc]
bopModel = bop;
bopModel.Title.String = "";
bode(Pdn, Pd, bopModel); %[output:7ea341fc]
legend("Model", "Measured", "Location", "northwest"); %[output:7ea341fc]
grid on; %[output:7ea341fc]
%%
%% Check stability and sensitivity before operating the stage
Smax = 2;

figure; %[output:14a7b9f0]
ny(1) = nyquistplot(Pdn*Kd, nop); hold on; %[output:14a7b9f0]
ny(2) = nyquistplot(Pd*Kd,nop); %[output:14a7b9f0]
theta = 0:0.01:2*pi;
plot(cos(theta)/Smax-1, sin(theta)/Smax, "k--"); hold off; %[output:14a7b9f0]
legend("Nominal", "Measured", "1/Smax boundary"); %[output:14a7b9f0]
title(""); %[output:14a7b9f0]

figure; %[output:3960dddf]
S = feedback(1, Pd*Kd);
SmaxFrd = frd(Smax*ones(numel(Pd.Frequency), 1), ...
    Pd.Frequency, "FrequencyUnit", "Hz");
bopSensitivity = bop;
bopSensitivity.XLim = {[1, 1e3]};
bodemag(S, bopSensitivity); hold on; %[output:3960dddf]
bodemag(SmaxFrd, bopSensitivity, "k--"); hold off; %[output:3960dddf]
legend("Measured", "Smax"); %[output:3960dddf]
title(""); %[output:3960dddf]
%%
%[text] ## 2. Generate the reference and feedforward input
dist = 0.84;       % Travel distance [m]
v_max = 1.0;      % Maximum velocity [m/s]
a_max = 17.0;      % Maximum acceleration [m/s^2]
t_pause = 1.0;    % Dwell at the turn-around point [s]
t_pre = 1.5;      % Idle time before motion [s]
t_post = 1.5;     % Idle time after motion [s]

traj = generateMyProfile_TrajectTools( ...
    0.0, dist, v_max, a_max/2, Ts, t_pause, t_pre, t_post);
t = traj.time;
r = traj.pos(:);
Tend = t(end);
N = numel(r);
feedbackFlag = 1;

figure; %[output:72529096]
tiledlayout(2, 1); %[output:72529096]
nexttile; plot(t, traj.pos); title("Position"); grid on; %[output:72529096]
ylabel("Position [m]"); %[output:72529096]
nexttile; plot(t, traj.vel); title("Velocity"); grid on; %[output:72529096]
xlabel("Time [s]"); ylabel("Velocity [m/s]"); %[output:72529096]
%%
%[text] ## Feedforward gains
%[text] These gains are experiment calibration knobs. Keep all gains zero for the feedback-only baseline; use Kfa for acceleration feedforward.
Kfj = 0;
Kfa = 0;
Kfv = 0;
Kfc = 0;
f = Kfj*traj.jerk + Kfa*traj.acc + Kfv*traj.vel ...
    + Kfc*sign(traj.vel);
f = [f(1+Ndelay:end); repmat(f(end), Ndelay, 1)];
%%
%[text] ## 3. Build the tunable model
%[text] Run this section after every sampleRateHz change. It calls `slbuild` and does not operate the servo. Publish/install the generated module, set the TwinCAT task to Ts, and activate the configuration before the experiment.
run(fullfile(projectRoot, "exp03_FF", "setup_tunable.m")); %[output:45698547] %[output:3768e1b6] %[output:39a74fae]
%%
%[text] ## 4. Run the experiment
%[text] **Operator action:** this section connects to external mode, enables the servo, moves the stage, and archives prior staged measurement parts before capture.
open(fullfile(projectRoot, ModelName))
[~, homing] = home_to_start(54100000);
run(fullfile(projectRoot, "exp03_FF", "obtainMeasurement.m")); %[output:55d50f92]
%%

count_ex = measurement(1, :);
t_ex = (count_ex(:)-count_ex(1))*Ts;
e_ex = measurement(2, :);             % Tracking error [m]
u_ex = measurement(3, :);             % Total control input [A]
v_ex = measurement(4, :);             % Velocity [m/s]
y_ex = measurement(5, :);             % Position [m]
ff_ex = measurement(7, :);            % Feedforward input [A]
y_absolute_ex = measurement(8, :);    % Absolute position [m]
r_ex = measurement(9, :);             % Recorded reference [m]
% Rows 6 and 10 are torque/current feedback and quantized reference.

lostPackages = setdiff(count_ex(1):count_ex(end), count_ex);
lostPackagesNum = numel(lostPackages);
fprintf("Lost packages: %d\n", lostPackagesNum); %[output:51b0183d]
assert(lostPackagesNum == 0 && all(diff(count_ex) == 1), ...
    "Measurement contains missing or out-of-order samples.");

figure; plot(diff(y_ex)/Ts); hold on; %[output:6c4e6e48]
plot(diff(r_ex)/Ts) %[output:6c4e6e48]
%%
%[text] ## Save the result
tol = 1e-12;
if all(abs(f) < tol)
    specialTag = "notSpecial";
else
    specialTag = "Special";
end
% Set specialTag = "only" manually for a position-dependent-only run.

fileName = sprintf("V%.3f_%s_Result", v_max, specialTag);
feedforwardResult = struct("t_ex", t_ex, "r", r, "y_ex", y_ex, ...
    "e_ex", e_ex, "u_ex", u_ex, "v_ex", v_ex, "ff_ex", ff_ex, ...
    "y_absolute_ex", y_absolute_ex, "Kd", Kd, "r_ex", r_ex, ...
    "Ts", Ts, "plantPath", plantPath, "homing", homing);
save_experiment_result(runDir, fileName, feedforwardResult); %[output:group:90665e0e] %[output:95c552b7]

%%
%[text] ## 5. Inspect the current result
figure; %[output:04081e31]
tiledlayout(3, 1); %[output:04081e31]
nexttile; plot(t_ex, r_ex, t_ex, y_ex); %[output:04081e31]
xlabel("Time [s]"); ylabel("Position [m]"); grid on; %[output:04081e31]
legend(["Reference", "Position"]); %[output:04081e31]
nexttile; plot(t_ex, e_ex); %[output:04081e31]
xlabel("Time [s]"); ylabel("Tracking error [m]"); grid on; %[output:04081e31]
nexttile; plot(t_ex, ff_ex, t_ex, u_ex-ff_ex); %[output:04081e31]
xlabel("Time [s]"); ylabel("Input [A]"); grid on; %[output:04081e31]
legend("FF", "FB"); %[output:04081e31]
linkaxes(findall(gcf, "Type", "axes"), "x"); %[output:04081e31]

fprintf("Tracking-error 2-norm: %.6g\n", norm(e_ex, 2)); %[output:935dae70]
save_experiment_figures(runDir, gcf);
%%
%[text] ## 6. Compare the latest three methods at one speed
%[text] The latest matching file is selected for each method. If a method is missing, this optional comparison is skipped.
if ~exist("runDir", "var") || ~isfolder(runDir)
    runDir = create_run_directory(fullfile(projectRoot, "data", "ff"), "comparison");
end
dataDir = fullfile(projectRoot, "data", "ff");
comparisonSpeed = 0.600;
comparisonTags = ["notSpecial", "Special", "only"];
comparisonData = struct();

for tag = comparisonTags %[output:group:755cd5dc]
    pattern = sprintf("V%.3f_%s_Result*.mat", comparisonSpeed, tag);
    matches = dir(fullfile(dataDir, "**", pattern));
    if isempty(matches)
        warning("No %s result at %.3f m/s.", tag, comparisonSpeed); %[output:7fbad5a6] %[output:2859ca0a] %[output:214a8232]
        continue
    end
    [~, latest] = max([matches.datenum]);
    comparisonData.(tag) = load(fullfile(matches(latest).folder, ...
        matches(latest).name));
end %[output:group:755cd5dc]

if all(isfield(comparisonData, cellstr(comparisonTags)))
    figure; hold on;
    plot(comparisonData.notSpecial.t_ex, comparisonData.notSpecial.e_ex, ...
        "DisplayName", "FB only");
    plot(comparisonData.only.t_ex, comparisonData.only.e_ex, ...
        "DisplayName", "Position-dependent only");
    plot(comparisonData.Special.t_ex, comparisonData.Special.e_ex, ...
        "DisplayName", "Proposed");
    hold off; grid on;
    xlabel("Time [s]"); ylabel("Tracking error [m]");
    legend("Location", "best");
end
%%
%[text] ## 7. Full-trace RMS and peak error by speed
if ~exist("runDir", "var") || ~isfolder(runDir)
    runDir = create_run_directory(fullfile(projectRoot, "data", "ff"), "comparison");
end
dataDir = fullfile(projectRoot, "data", "ff");
files = dir(fullfile(dataDir, "**", "V*_Result*.mat"));
speedNot = []; rmsNot = []; peakNot = [];
speedSpecial = []; rmsSpecial = []; peakSpecial = [];

for k = 1:numel(files)
    token = regexp(files(k).name, "V([\d\.]+)_", "tokens", "once");
    if isempty(token), continue; end
    speed = str2double(token{1});
    result = load(fullfile(files(k).folder, files(k).name));
    if ~isfield(result, "e_ex"), continue; end
    errorSignal = result.e_ex(:);
    rmsError = sqrt(mean(errorSignal.^2));
    peakError = norm(errorSignal, inf);

    if contains(files(k).name, "notSpecial")
        speedNot(end+1) = speed; %#ok<SAGROW>
        rmsNot(end+1) = rmsError; %#ok<SAGROW>
        peakNot(end+1) = peakError; %#ok<SAGROW>
    elseif contains(files(k).name, "Special")
        speedSpecial(end+1) = speed; %#ok<SAGROW>
        rmsSpecial(end+1) = rmsError; %#ok<SAGROW>
        peakSpecial(end+1) = peakError; %#ok<SAGROW>
    end
end

[speedNot, order] = sort(speedNot);
rmsNot = rmsNot(order); peakNot = peakNot(order);
[speedSpecial, order] = sort(speedSpecial);
rmsSpecial = rmsSpecial(order); peakSpecial = peakSpecial(order);

figure; hold on; grid on; %[output:68d021a3]
plot(speedNot, rmsNot, "o-", "DisplayName", "Without FF"); %[output:68d021a3]
plot(speedSpecial, rmsSpecial, "s-", "DisplayName", "With FF");
xlabel("Velocity [m/s]"); ylabel("RMS tracking error [m]"); %[output:68d021a3]
legend("Location", "best"); %[output:68d021a3]

figure; hold on; grid on; %[output:00b3d6c1]
plot(speedNot, peakNot, "o-", "DisplayName", "Without FF"); %[output:00b3d6c1]
plot(speedSpecial, peakSpecial, "s-", "DisplayName", "With FF");
xlabel("Velocity [m/s]"); ylabel("Peak tracking error [m]"); %[output:00b3d6c1]
legend("Location", "best"); %[output:00b3d6c1]
%%
%[text] ## 8. Forward/return constant-velocity analysis
if ~exist("runDir", "var") || ~isfolder(runDir)
    runDir = create_run_directory(fullfile(projectRoot, "data", "ff"), "comparison");
end
dataDir = fullfile(projectRoot, "data", "ff");
files = dir(fullfile(dataDir, "**", "V*_Result*.mat"));

if isempty(files)
    warning("No feedforward result files were found in %s.", dataDir);
else
    velTol = 1e-5;
    accTolMin = 1e-7;
    accRel = 1e-7;

    speedFbF = []; rmsFbF = []; peakFbF = [];
    speedFbR = []; rmsFbR = []; peakFbR = [];
    speedPosF = []; rmsPosF = []; peakPosF = [];
    speedPosR = []; rmsPosR = []; peakPosR = [];
    speedPropF = []; rmsPropF = []; peakPropF = [];
    speedPropR = []; rmsPropR = []; peakPropR = [];

    for k = 1:numel(files)
        result = load(fullfile(files(k).folder, files(k).name));
        if ~isfield(result, "r_ex") || ~isfield(result, "e_ex")
            warning("r_ex/e_ex is missing: %s", files(k).name);
            continue
        end

        resultTs = result_sample_period(result);
        if isempty(resultTs)
            warning("Ts is missing; skipping sample-rate-unsafe analysis: %s", ...
                files(k).name);
            continue
        end
        [pair, message] = split_forward_return( ...
            result.r_ex, result.e_ex, resultTs, velTol, accTolMin, accRel);
        if isempty(fieldnames(pair))
            warning("%s: %s", files(k).name, message);
            continue
        end

        segments = {pair.forward, pair.return};
        for segmentIndex = 1:2
            segment = segments{segmentIndex};
            speed = segment.mean_vel;
            rmsError = sqrt(mean(segment.e.^2));
            peakError = norm(segment.e, inf);
            forward = speed >= 0;

            if contains(files(k).name, "notSpecial")
                if forward
                    speedFbF(end+1) = speed; rmsFbF(end+1) = rmsError; peakFbF(end+1) = peakError; %#ok<SAGROW>
                else
                    speedFbR(end+1) = speed; rmsFbR(end+1) = rmsError; peakFbR(end+1) = peakError; %#ok<SAGROW>
                end
            elseif contains(files(k).name, "only")
                if forward
                    speedPosF(end+1) = speed; rmsPosF(end+1) = rmsError; peakPosF(end+1) = peakError; %#ok<SAGROW>
                else
                    speedPosR(end+1) = speed; rmsPosR(end+1) = rmsError; peakPosR(end+1) = peakError; %#ok<SAGROW>
                end
            elseif contains(files(k).name, "Special")
                if forward
                    speedPropF(end+1) = speed; rmsPropF(end+1) = rmsError; peakPropF(end+1) = peakError; %#ok<SAGROW>
                else
                    speedPropR(end+1) = speed; rmsPropR(end+1) = rmsError; peakPropR(end+1) = peakError; %#ok<SAGROW>
                end
            end
        end
    end

    [speedFbF, order] = sort(speedFbF); rmsFbF = rmsFbF(order); peakFbF = peakFbF(order);
    [speedFbR, order] = sort(speedFbR); rmsFbR = rmsFbR(order); peakFbR = peakFbR(order);
    [speedPosF, order] = sort(speedPosF); rmsPosF = rmsPosF(order); peakPosF = peakPosF(order);
    [speedPosR, order] = sort(speedPosR); rmsPosR = rmsPosR(order); peakPosR = peakPosR(order);
    [speedPropF, order] = sort(speedPropF); rmsPropF = rmsPropF(order); peakPropF = peakPropF(order);
    [speedPropR, order] = sort(speedPropR); rmsPropR = rmsPropR(order); peakPropR = peakPropR(order);

    colors = struct( ...
        "fb", [0.25, 0.25, 0.25], ...
        "pos", [0.65, 0.65, 0.65], ...
        "prop", [0.30, 0.50, 0.70]);
    lineWidth = 1.8;
    markerSize = 7;

    figure; hold on; grid on;
    pFb = plot(speedFbF, rmsFbF, "-^", "Color", colors.fb, ...
        "LineWidth", lineWidth, "MarkerSize", markerSize);
    plot(-speedFbR, rmsFbR, "-v", "Color", colors.fb, ...
        "LineWidth", lineWidth, "MarkerSize", markerSize);
    pPos = plot(speedPosF, rmsPosF, "-^", "Color", colors.pos, ...
        "LineWidth", lineWidth, "MarkerSize", markerSize);
    plot(-speedPosR, rmsPosR, "-v", "Color", colors.pos, ...
        "LineWidth", lineWidth, "MarkerSize", markerSize);
    pProp = plot(speedPropF, rmsPropF, "-^", "Color", colors.prop, ...
        "LineWidth", lineWidth, "MarkerSize", markerSize);
    plot(-speedPropR, rmsPropR, "-v", "Color", colors.prop, ...
        "LineWidth", lineWidth, "MarkerSize", markerSize);
    xlabel("Velocity [m/s]"); ylabel("RMS tracking error [m]");
    legend([pFb, pPos, pProp], ...
        {"FB only", "Position-dependent only", "Proposed"}, ...
        "Location", "best", "Box", "off");
    text(0.02, 0.98, "\Delta: forward   \nabla: return", ...
        "Units", "normalized", "VerticalAlignment", "top", ...
        "BackgroundColor", "w");

    figure; hold on; grid on;
    plot(speedFbF, peakFbF, "o-", "DisplayName", "FB only (forward)");
    plot(-speedFbR, peakFbR, "o--", "DisplayName", "FB only (return)");
    plot(speedPosF, peakPosF, "s-", "DisplayName", "Position-dependent only (forward)");
    plot(-speedPosR, peakPosR, "s--", "DisplayName", "Position-dependent only (return)");
    plot(speedPropF, peakPropF, "^-", "DisplayName", "Proposed (forward)");
    plot(-speedPropR, peakPropR, "^--", "DisplayName", "Proposed (return)");
    xlabel("Velocity [m/s]"); ylabel("Peak tracking error [m]");
    legend("Location", "best");

    ilc = load_ilc_summary(fullfile(projectRoot, "data", "ilc"), ...
        velTol, accTolMin, accRel);
    figure; hold on; grid on;
    semilogy(speedFbF, rmsFbF, "o-", "DisplayName", "FB only (forward)");
    semilogy(-speedFbR, rmsFbR, "o--", "DisplayName", "FB only (return)");
    semilogy(speedPosF, rmsPosF, "s-", "DisplayName", "Position-dependent only (forward)");
    semilogy(-speedPosR, rmsPosR, "s--", "DisplayName", "Position-dependent only (return)");
    semilogy(speedPropF, rmsPropF, "^-", "DisplayName", "Proposed (forward)");
    semilogy(-speedPropR, rmsPropR, "^--", "DisplayName", "Proposed (return)");
    if isfield(ilc, "forward") && isfield(ilc, "return_")
        plot(ilc.forward.speed(:), ilc.forward.rms(:), "k^", ...
            "LineWidth", 1.5, "DisplayName", "ILC (forward)");
        plot(-ilc.return_.speed(:), ilc.return_.rms(:), "kv", ...
            "LineWidth", 1.5, "DisplayName", "ILC (return)");
    end
    xlabel("Velocity [m/s]"); ylabel("RMS tracking error [m]");
    legend("Location", "best");

    figure; hold on; grid on;
    semilogy(speedFbF, peakFbF, "o-", "DisplayName", "FB only (forward)");
    semilogy(-speedFbR, peakFbR, "o--", "DisplayName", "FB only (return)");
    semilogy(speedPosF, peakPosF, "s-", "DisplayName", "Position-dependent only (forward)");
    semilogy(-speedPosR, peakPosR, "s--", "DisplayName", "Position-dependent only (return)");
    semilogy(speedPropF, peakPropF, "^-", "DisplayName", "Proposed (forward)");
    semilogy(-speedPropR, peakPropR, "^--", "DisplayName", "Proposed (return)");
    if isfield(ilc, "forward") && isfield(ilc, "return_")
        plot(ilc.forward.speed(:), ilc.forward.inf_norm(:), "k^", ...
            "LineWidth", 1.5, "DisplayName", "ILC (forward)");
        plot(-ilc.return_.speed(:), ilc.return_.inf_norm(:), "kv", ...
            "LineWidth", 1.5, "DisplayName", "ILC (return)");
    end
    xlabel("Velocity [m/s]"); ylabel("Peak tracking error [m]");
    legend("Location", "best");
end
save_experiment_figures(runDir, findall(groot, "Type", "figure"));

function Ts = result_sample_period(result)
Ts = [];
if isfield(result, "Ts") && isscalar(result.Ts) && result.Ts > 0
    Ts = result.Ts;
elseif isfield(result, "t_ex") && numel(result.t_ex) >= 2
    Ts = median(diff(result.t_ex(:)));
elseif isfield(result, "history") && isfield(result.history, "t") && ...
        numel(result.history.t) >= 2
    Ts = median(diff(result.history.t(:)));
end
if isempty(Ts) || ~isfinite(Ts) || Ts <= 0
    Ts = [];
end
end

function ilc = load_ilc_summary(ilcDir, velTol, accTolMin, accRel)
ilc = struct();
summaryFiles = dir(fullfile(ilcDir, "**", "rms_summary.mat"));
if ~isempty(summaryFiles)
    [~, latestSummary] = max([summaryFiles.datenum]);
    ilc = load(fullfile(summaryFiles(latestSummary).folder, ...
        summaryFiles(latestSummary).name));
    return
end

files = dir(fullfile(ilcDir, "**", "ilc_result_V*.mat"));
forwardSpeed = []; forwardRms = []; forwardPeak = [];
returnSpeed = []; returnRms = []; returnPeak = [];
for k = 1:numel(files)
    result = load(fullfile(files(k).folder, files(k).name));
    if ~isfield(result, "history") || ~isfield(result.history, "r") || ...
            ~isfield(result.history, "e")
        continue
    end
    Ts = result_sample_period(result);
    if isempty(Ts)
        continue
    end
    trial = size(result.history.e, 2);
    if isfield(result, "completedTrials")
        trial = min(trial, result.completedTrials);
    end
    if trial < 1
        continue
    end
    [pair, ~] = split_forward_return(result.history.r(:, trial), ...
        result.history.e(:, trial), Ts, velTol, accTolMin, accRel);
    if isempty(fieldnames(pair))
        continue
    end
    forwardSpeed(end+1) = pair.forward.mean_vel; %#ok<AGROW>
    forwardRms(end+1) = sqrt(mean(pair.forward.e.^2)); %#ok<AGROW>
    forwardPeak(end+1) = norm(pair.forward.e, inf); %#ok<AGROW>
    returnSpeed(end+1) = pair.return.mean_vel; %#ok<AGROW>
    returnRms(end+1) = sqrt(mean(pair.return.e.^2)); %#ok<AGROW>
    returnPeak(end+1) = norm(pair.return.e, inf); %#ok<AGROW>
end
if ~isempty(forwardSpeed)
    ilc.forward = struct("speed", forwardSpeed, "rms", forwardRms, ...
        "inf_norm", forwardPeak);
    ilc.return_ = struct("speed", returnSpeed, "rms", returnRms, ...
        "inf_norm", returnPeak);
end
end

function [pair, message] = split_forward_return(r, e, Ts, velTol, accTolMin, accRel)
pair = struct();
message = "";
n = min(numel(r), numel(e));
r = r(1:n);
e = e(1:n);
if n < 3
    message = "Not enough samples";
    return
end

[velocity, acceleration] = compute_vel_acc(r, Ts);
accTol = max(accTolMin, accRel*max(1, max(abs(acceleration))));
runs = find_runs(abs(acceleration) <= accTol & abs(velocity) > velTol);
segments = struct("idx", {}, "e", {}, "dir", {}, "range", {}, "mean_vel", {});

for i = 1:size(runs, 1)
    index = runs(i, 1):runs(i, 2);
    if numel(index) < 3, continue; end
    rSegment = r(index);
    direction = sign(median(diff(rSegment)));
    if direction == 0, continue; end
    segments(end+1).idx = index; %#ok<AGROW>
    segments(end).e = e(index);
    segments(end).dir = direction;
    segments(end).range = [min(rSegment), max(rSegment)];
    segments(end).mean_vel = median(velocity(index));
end

if numel(segments) < 2
    message = "Forward/return constant-velocity segments were not found";
    return
end

bestWidth = -inf;
bestPair = [];
for i = 1:numel(segments)-1
    for j = i+1:numel(segments)
        if segments(i).dir*segments(j).dir ~= -1, continue; end
        overlap = min(segments(i).range(2), segments(j).range(2)) ...
            - max(segments(i).range(1), segments(j).range(1));
        if overlap > bestWidth
            bestWidth = overlap;
            bestPair = [i, j];
        end
    end
end

if isempty(bestPair) || bestWidth <= 0
    message = "The forward and return position ranges do not overlap";
    return
end

forward = segments(bestPair(1));
returnSegment = segments(bestPair(2));
if forward.dir < 0
    [forward, returnSegment] = deal(returnSegment, forward);
end
pair.forward = forward;
pair.return = returnSegment;
end

function [velocity, acceleration] = compute_vel_acc(r, Ts)
r = r(:);
n = numel(r);
velocity = zeros(n, 1);
acceleration = zeros(n, 1);
if n >= 2
    velocity(1) = (r(2)-r(1))/Ts;
    velocity(end) = (r(end)-r(end-1))/Ts;
end
if n >= 3
    velocity(2:end-1) = (r(3:end)-r(1:end-2))/(2*Ts);
end
if n >= 2
    acceleration(1) = (velocity(2)-velocity(1))/Ts;
    acceleration(end) = (velocity(end)-velocity(end-1))/Ts;
end
if n >= 3
    acceleration(2:end-1) = (velocity(3:end)-velocity(1:end-2))/(2*Ts);
end
end

function runs = find_runs(mask)
edges = diff([false; logical(mask(:)); false]);
runs = [find(edges == 1), find(edges == -1)-1];
end

